#!/usr/bin/env node
/**
 * Fail if an agent branch touched a path it does not own (CONTRACTS §0).
 *
 *   npm run agents:check <data|backend|design|frontend>            # branch vs origin/main
 *   npm run agents:check <data|backend|design|frontend> -- --staged
 *
 * Agents run this before every commit; the lead runs it before every merge.
 * Shares its ownership table with the guard hook (ownership.mjs).
 * Lead-owned — agents do not edit this file.
 */
import { execFileSync } from 'node:child_process';
import { AGENTS, ownershipViolation } from './ownership.mjs';

const [agent, ...flags] = process.argv.slice(2);
const staged = flags.includes('--staged');

if (!AGENTS.includes(agent)) {
  console.error(`usage: npm run agents:check <${AGENTS.join('|')}> [-- --staged]`);
  process.exit(2);
}

const git = (...args) => execFileSync('git', args, { encoding: 'utf8' }).trim();

let changed;
let scope;
if (staged) {
  changed = git('diff', '--cached', '--name-only');
  scope = 'staged changes';
} else {
  let base;
  try {
    base = git('merge-base', 'origin/main', 'HEAD');
  } catch {
    base = git('merge-base', 'main', 'HEAD');
  }
  changed = git('diff', '--name-only', `${base}...HEAD`);
  scope = `commits since ${base.slice(0, 7)}`;
}

const files = changed.split('\n').filter(Boolean);
if (files.length === 0) {
  console.log(`[${agent}] no changes in ${scope} — nothing to check`);
  process.exit(0);
}

const violations = files
  .map((f) => [f, ownershipViolation(agent, f)])
  .filter(([, v]) => v !== null);

if (violations.length > 0) {
  console.error(`[${agent}] ✗ paths outside your ownership in ${scope}:`);
  for (const [f, v] of violations) console.error(`    ${f.padEnd(52)} ${v}`);
  console.error('');
  console.error('  Revert them. If you genuinely need a change there, write it under');
  console.error(`  "Contract change requests" in docs/agents/status/${agent}.md and continue`);
  console.error('  against the current contract (CLAUDE.md → File ownership).');
  process.exit(1);
}

console.log(`[${agent}] ✓ ${files.length} file(s) in ${scope}, all inside owned paths`);
